mapper.select:
   SELECT * FROM yh_user_temperature
WHERE  e_user_id=#{usercode} AND Is_Del=2

     AND Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


     AND Entry_Time LIKE CONCAT('',#{strTime},'%')


     AND YEAR(Entry_Time) =#{strTime}


     SELECT COUNT(1) FROM (SELECT * FROM `yh_user_temperature` WHERE `E_User_Id`=#{usercode} AND Is_Del=2

       AND  Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


       AND  Entry_Time LIKE CONCAT('',#{strTime},'%')


       AND YEAR(Entry_Time) =#{strTime}


     LIMIT #{page}) AS a
WHERE 	  CAST(a.temperature AS DECIMAL(10,2))>=37.3 AND CAST(a.temperature AS DECIMAL(10,2))	<=38


   SELECT COUNT(1) FROM (SELECT * FROM `yh_user_temperature` WHERE `E_User_Id`=#{usercode} AND Is_Del=2

       AND Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


       AND  Entry_Time LIKE CONCAT('',#{strTime},'%')


       AND  YEAR(Entry_Time) =#{strTime}


     LIMIT #{page}) AS a
WHERE 	 CAST(a.temperature AS DECIMAL(10,2)) > 38


   SELECT COUNT(1) FROM (SELECT * FROM `yh_user_temperature` WHERE `E_User_Id`=#{usercode} AND Is_Del=2

       AND Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


       AND Entry_Time LIKE CONCAT('',#{strTime},'%')


       AND YEAR(Entry_Time) =#{strTime}


     LIMIT #{page}) AS a
WHERE 	  CAST(a.temperature AS DECIMAL(10,2))>=36 AND CAST(a.temperature AS DECIMAL(10,2))<=37.2


   SELECT COUNT(1) FROM (SELECT * FROM `yh_user_temperature` WHERE `E_User_Id`=#{usercode} AND Is_Del=2


       AND Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


       AND Entry_Time LIKE CONCAT('',#{strTime},'%')


       AND YEAR(Entry_Time) =#{strTime}


     LIMIT #{page}) AS a
WHERE 	  CAST(a.temperature AS DECIMAL(10,2))  < 36
